async function runImport(input){
  const out = $('#impOut');
  if(!out || !window.WH_IMPORT) return;
  if(typeof input === 'string' && !input.trim()){ out.innerHTML = '<div class="impno"><p class="qh">Nothing to import</p><p class="lead">Choose the file, or paste the export first.</p></div>'; return; }
  let r; try { r = await WH_IMPORT.read(input, D); } catch(e){ r = { ok:false, errors:['not a New Recruit export (it could not be read)'] }; }
  if(!r.ok) return impFail('Not imported · ' + r.errors.length + (r.errors.length === 1 ? ' reason' : ' reasons'), r.errors);
  let id; try { id = await WH_IMPORT.localId(r.kept); } catch(e){ return impFail('Not imported', ['this browser cannot keep imported lists (no WebCrypto)']); }
  const kept = importedKept();
  if(kept.some(y => y.id === id) && id !== impReplace){ const y = D.armies.find(a => a.id === id);
    out.innerHTML = '<div class="impno"><p class="qh">Already imported</p><p class="lead">This export is already on this phone' + (y ? ' as ' + esc(y.name) : '') + '.</p>' + (y ? '<div class="racts"><button class="btn" data-army="' + esc(id) + '">Open ' + esc(y.name) + '</button></div>' : '') + '</div>'; return; }
  const date = today();
  // (the name in the box, else the export's: prefilled from it when the export carries one, else "Imported list")
  const box = $('#impName'), given = box && box.value.trim() ? box.value.trim() : '';
  if(box && !given){ const n = WH_IMPORT.nameOf(r.kept, D); if(n) box.value = n; }
  const listName = given || null;
  let m; try { m = WH_IMPORT.make(r.kept, D, { id, date, name:listName }); } catch(e){ m = { ok:false, errors:['not a New Recruit export (it could not be read)'] }; }
  if(!m.ok) return impFail('Not imported · ' + m.errors.length + (m.errors.length === 1 ? ' reason' : ' reasons'), m.errors);
  const A = m.army;
  // (Update: the list it replaces goes; the same export again keeps its id, and with it its star, ticks and checklist)
  if(impReplace && impReplace !== id) removeKept(impReplace);
  { const k = importStale.findIndex(y => y.id === id); if(k >= 0) importStale.splice(k, 1); }
  try { store.set(IMPORT_KEY, importedKept().filter(y => y.id !== id).concat([Object.assign({ id, name:A.name, date, json:r.kept }, listName ? { listName } : {})])); } catch(e){}
  const saved = importedKept().some(x => x.id === id);
  const i = D.armies.findIndex(y => y.id === id); if(i >= 0) D.armies.splice(i, 1);
  D.armies.push(splitRefs(A)); ONLY = D.armies.length === 1 ? D.armies[0] : null;
  impReplace = null;
  hideSheet(); go({ s:'army', army:id }, 'sheet');
  toast(saved ? 'Imported ' + A.name : 'Imported ' + A.name + ' for now: this phone could not keep it');
}

const importedFoot = a => { const x = importedKept().find(y => y.id === a.id);
  return '<div class="sec-h"><h2>On this phone</h2></div><p class="note">Imported from New Recruit' + (x && x.date ? ' on ' + esc(x.date) : '') + '. ' +
    (a.built ? 'Built from its export and the app’s ' + esc(factionOf(a).name) + ' tables, as the app’s own lists are. ' : 'Copied from units the app’s own lists have: ' + esc(factionOf(a).name) + ' has no full catalogue in the app yet. ') +
    (x ? 'Kept on this phone only.' : 'This phone could not keep it: it is gone when the app next starts.') + '</p>' +
    ((a.gwPoints || []).length ? '<p class="note">Points: GW’s are used where the export’s differ: ' + a.gwPoints.map(g => esc(g.unit) + ' ' + g.export + ' pts in the export, ' + g.gw + ' pts by GW').join('; ') + '.</p>' : '') +
    '<div class="imprm" id="impRm">' + impRmBtn(a.id) + '</div>'; };

function removeKept(id){
  store.set(IMPORT_KEY, importedKept().filter(y => y.id !== id));
  const i = D.armies.findIndex(y => y.id === id && y.imported); if(i >= 0) D.armies.splice(i, 1);
  const j = importStale.findIndex(y => y.id === id); if(j >= 0) importStale.splice(j, 1);
  try { localStorage.removeItem('wh-used-' + id); localStorage.removeItem('wh-check-' + id); } catch(e){}
  if(favIds().includes(id)) setFav(id, false);
}

function removeImported(id){
  const a = armyById(id), x = importedKept().find(y => y.id === id), name = (a || x || {}).name || 'the list';
  removeKept(id);
  ONLY = D.armies.length === 1 ? D.armies[0] : null;
  hideSheet(); go({ s:'home' }, 'replace');
  toast('Removed ' + name);
}
